114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
118	        owner.setTelephone(normalizedTelephone);
119	        owner.setEmail(normalizeEmail(owner.getEmail()));
120	        owner.setAddress(normalizeAddress(owner.getAddress()));
121	        validatePostcode(owner.getCity(), owner.getPostcode());
122	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
123	        if (effectiveRegistrationDate == null) {
124	            effectiveRegistrationDate = LocalDate.now();
125	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
126	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
127	                "registrationDate must not be later than the current server date");
128	        }
129	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
130	        owner.setRegistrationDate(effectiveRegistrationDate);
131	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
132	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
133	                "the maximum number of owners that may be created today has been reached");
134	        }
135	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
136	        if (sharesHousehold) {
137	            this.clinicService.assignHousehold(owner);
138	        }
139	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
140	            throw new ResponseStatusException(HttpStatus.CONFLICT,
141	                "an owner with the same identity already exists");
142	        }
143	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
144	            throw new ResponseStatusException(HttpStatus.CONFLICT,
145	                "city has reached its maximum number of owners");
146	        }
147	        owner.setCustomerCode(customerCodeFor(owner));
148	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
149	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
150	        owner.setBulkSignupWarning(
151	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
152	        this.clinicService.saveOwner(owner);
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
155	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
156	            ownerDto.getMembershipLevel());
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
